#' Calculate and Plot Variable Importance from Model Ensemble
#'
#' Extracts or calculates variable importance scores from a list of fitted model
#' objects (typically generated by `trainModel`). It calculates the mean and
#' standard error of importance across the ensemble and generates a bar plot.
#' Note: Importance metrics are algorithm-specific. Boosted trees use relative
#' influence, XGBoost uses gain, and GLM and Maxent use permutation importance
#' on a sample of up to 2000 raster cells. Each model in the ensemble is
#' measured separately.
#'
#' @param models The list returned by [trainModel()].
#' @param rasterLayers A terra `SpatRaster` whose layer names are the predictors
#'   used to fit the models.
#' @export
#' @importFrom stats sd reorder cor
#' @importFrom ggplot2 ggplot aes geom_bar geom_errorbar coord_flip theme_bw theme element_text element_blank element_line labs geom_hline annotate position_dodge margin
#' @importFrom gbm summary.gbm
#' @importFrom xgboost xgb.importance getinfo
#' @importFrom terra spatSample nlyr ncell
#'

variableContribution <- function(models,rasterLayers) {

  if (!inherits(rasterLayers, "SpatRaster")) {
    stop("Error :: rasterLayers must be a SpatRaster")
  }
  algorithmModels <- models$model
  if (is.null(algorithmModels) || length(algorithmModels) == 0) {
    stop("Error :: models must be the list returned by trainModel")
  }

  algorithmType <- class(algorithmModels[[1]])[1]
  relativeImportanceMatrix <- matrix(NA, ncol = length(algorithmModels), nrow = terra::nlyr(rasterLayers))
  rownames(relativeImportanceMatrix) <- names(rasterLayers)

  perm_importance <- function(modelM, data, type) {
    base_pred <- as.numeric(predict(modelM, data, type = type))
    vars <- colnames(data)
    imp <- numeric(length(vars))
    names(imp) <- vars
    for (v in vars) {
      data_perm <- data
      data_perm[[v]] <- sample(data_perm[[v]])
      pred_perm <- as.numeric(predict(modelM, data_perm, type = type))
      association <- stats::cor(pred_perm, base_pred)
      imp[v] <- if (is.finite(association)) 1 - association else NA_real_
    }
    if (!is.finite(sum(imp, na.rm = TRUE)) || sum(imp, na.rm = TRUE) == 0) return(imp)
    imp / sum(imp, na.rm = TRUE)
  }

  sampled <- NULL
  if (algorithmType %in% c("maxnet", "glm")) {
    sampled <- terra::spatSample(
      rasterLayers,
      size = min(2000, terra::ncell(rasterLayers)),
      method = "random",
      na.rm = TRUE,
      as.df = TRUE,
      warn = FALSE
    )
    if (nrow(sampled) < 10) stop("Error :: not enough non-NA cells to estimate variable importance")
  }

  if( algorithmType == "gbm" ) {
    for(m in seq_along(algorithmModels)) {
      relativeImportance.m <- summary(algorithmModels[[m]], plotit = FALSE)
      relativeImportanceMatrix[,m] <- relativeImportance.m[match(names(rasterLayers), relativeImportance.m$var), "rel.inf"]
    }
  } else if( algorithmType %in% c("xgboost","xgb.Booster") ) {
    for(m in seq_along(algorithmModels)) {
      relativeImportance.m = as.data.frame(xgboost::xgb.importance(xgboost::getinfo(algorithmModels[[m]], "feature_name"), model = algorithmModels[[m]])[,1:2])
      relativeImportanceMatrix[,m] <- relativeImportance.m[match(names(rasterLayers), relativeImportance.m$Feature), "Gain"]
    }
  } else if( algorithmType == "maxnet" ) {
    for(m in seq_along(algorithmModels)) {
      importance <- perm_importance(algorithmModels[[m]], sampled, type = "cloglog")
      relativeImportanceMatrix[,m] <- importance[names(rasterLayers)]
    }
  } else if( algorithmType == "glm" ) {
    for(m in seq_along(algorithmModels)) {
      importance <- perm_importance(algorithmModels[[m]], sampled, type = "response")
      relativeImportanceMatrix[,m] <- importance[names(rasterLayers)]
    }
  } else {
    stop("Error :: variable importance is not implemented for models of class ", algorithmType)
  }

  relativeImportance <- data.frame(
    Predictor = names(rasterLayers),
    relImportance = apply(relativeImportanceMatrix, 1, mean, na.rm = TRUE),
    relImportance.sd = apply(relativeImportanceMatrix, 1, stats::sd, na.rm = TRUE)
  )
  relativeImportance[is.na(relativeImportance)] <- 0
  if (algorithmType != "gbm" && sum(relativeImportance$relImportance) > 0) {
    relativeImportance$relImportance.sd <- relativeImportance$relImportance.sd / sum(relativeImportance$relImportance) * 100
    relativeImportance$relImportance <- relativeImportance$relImportance / sum(relativeImportance$relImportance) * 100
  }

  ## ----------

  relativeImportance$relImportance.sd <- relativeImportance$relImportance.sd / sqrt(length(algorithmModels))

  relativeImportancePlot <- ggplot(data=relativeImportance[sort(relativeImportance[,2],decreasing = TRUE,index.return=TRUE)$ix,]) +
    geom_bar( aes(x= reorder(Predictor, relImportance) , y=relImportance), stat="identity", fill="#ffd45b", alpha=0.85) +
    geom_errorbar( aes(x= reorder(Predictor, relImportance), ymin=relImportance-ifelse(relImportance.sd == 0, NA, relImportance.sd), ymax=relImportance+ifelse(relImportance.sd == 0, NA, relImportance.sd)), width=.1, alpha=0.8, linewidth=0.4, position=position_dodge(.9))  +
    coord_flip() +
    theme_bw() +
    theme(
      axis.text=element_text(size=10),
      axis.title.x = element_text(margin = margin(t = 10, r = 0, b = 0, l = 0) , size=13.5),
      axis.title.y = element_text(margin = margin(t = 0, r = 10, b = 0, l = 0) , size=13.5),
      panel.border = element_blank(),
      panel.background = element_blank(),
      panel.grid.major.y = element_blank(),
      panel.grid.major = element_line(linewidth = 0.25, linetype = 'solid',colour = "#EFEFEF"),
      panel.grid.minor = element_line(linewidth = 0, linetype = 'solid',colour = "#EFEFEF")
    ) + labs(x = "") +
    labs(y = "Relative importance (%)") + geom_hline(aes(yintercept=5 ),color="Black", linetype="dashed", linewidth=0.3) +
    annotate("text", y = 5 + 1 , x = 1 , label = "5%" , hjust = 0) + geom_hline(aes(yintercept=0 ),color="Gray", linewidth=0.3)

  relativeContribution <- list(dataFrame=relativeImportance,plot=relativeImportancePlot)
  return(relativeContribution)

}

